/* @autogenerated */
import { parseCell } from './cell-parse';
import { ImportPlanColumn } from './entity-import.model';

const column = (type: ImportPlanColumn['type'], extra: Partial<ImportPlanColumn> = {}): ImportPlanColumn => ({
  field: 'f',
  label: 'Campo',
  index: 0,
  type,
  ...extra,
});

describe('parseCell', () => {
  it('treats empty cells as no value', () => {
    expect(parseCell(null, column('text'))).toEqual({ value: undefined });
    expect(parseCell('   ', column('boolean'))).toEqual({ value: undefined });
  });

  it('trims text and stringifies numbers', () => {
    expect(parseCell('  ana ', column('text'))).toEqual({ value: 'ana' });
    expect(parseCell(123, column('text'))).toEqual({ value: '123' });
  });

  it('reads booleans in several languages', () => {
    expect(parseCell('Sí', column('boolean'))).toEqual({ value: true });
    expect(parseCell('x', column('boolean'))).toEqual({ value: true });
    expect(parseCell(0, column('boolean'))).toEqual({ value: false });
    expect(parseCell('no', column('boolean'))).toEqual({ value: false });
    expect(parseCell('quizá', column('boolean'))).toEqual({
      error: { key: 'common.import.error.invalid.boolean', params: { field: 'Campo', value: 'quizá' } },
    });
  });

  it('reads numbers with either decimal separator', () => {
    expect(parseCell('1.234,5', column('number'))).toEqual({ value: 1234.5 });
    expect(parseCell('1,234.5', column('number'))).toEqual({ value: 1234.5 });
    expect(parseCell(7, column('number'))).toEqual({ value: 7 });
    expect('error' in parseCell('abc', column('number'))).toBeTrue();
  });

  it('reads day-first and ISO dates as local dates', () => {
    expect(parseCell('05/03/2026 10:30', column('datetime'))).toEqual({ value: new Date(2026, 2, 5, 10, 30) });
    expect(parseCell('2026-03-05', column('date'))).toEqual({ value: new Date(2026, 2, 5) });
    expect(parseCell(new Date(2026, 2, 5, 18), column('date'))).toEqual({ value: new Date(2026, 2, 5) });
    expect('error' in parseCell('mañana', column('datetime'))).toBeTrue();
  });

  it('matches enum options by value or translated label', () => {
    const status = column('enum', {
      options: [
        { value: 'accepted', names: ['accepted', 'ACEPTADO'] },
        { value: 'pending', names: ['pending', 'PREVIO'] },
      ],
    });

    expect(parseCell('aceptado', status)).toEqual({ value: 'accepted' });
    expect(parseCell('PENDING', status)).toEqual({ value: 'pending' });
    expect('error' in parseCell('otro', status)).toBeTrue();
  });
});
